```json
[
  {
    "name": "HOTEL R9 The Yard Isumi",
    "summary": "This unique hotel offers accommodations in innovative shipping containers, providing a comfortable and convenient stay at a low cost. While generally clean and well-lit, some guests have noted issues with noise and shaking when others walk on the connected outdoor balcony."
  },
  {
    "name": "Hotel Galaxy",
    "summary": "A former love hotel now welcoming families, Hotel Galaxy offers spacious rooms and baths in a clean, though older, building. Guests appreciate the kind owner, snack availability, and convenient location for beach or golf trips, although some note the mattresses could use an update."
  },
  {
    "name": "Denkurō",
    "summary": "Denkurō is a retro inn, conveniently located for fishing, offering clean accommodations and a friendly atmosphere. Guests rave about the delicious blowfish dishes and exceptional service, though some find the standard meals disappointing and note road noise may be a concern."
  },
  {
    "name": "Seage Torami Coastside（セルジュ）東浪見 千葉",
    "summary": "This lodging offers an excellent location, just a minute's walk to the surf. However, some guests have reported negative experiences with staff unhelpfulness and noise disturbances due to proximity to the road and nearby construction."
  },
  {
    "name": "Sayan Terrace Hotel",
    "summary": "Sayan Terrace Hotel boasts a nice location near the beach with sea views, a mini pool, and customer parking. However, some guests have reported issues with cleanliness, outdated amenities, inhospitable staff, and a lack of accessibility for suitcases or wheelchairs, suggesting better lodging options may be available in the area."
  },
  {
    "name": "tokoro hotel Isumi",
    "summary": "Tokoro Hotel Isumi offers a spacious and uniquely designed renovated kominka experience with a separate bathhouse featuring a sauna and an open-air bath. While generally pleasant, some guests have noted minor issues with window privacy, the heater in the bathhouse, and occasional cleaning oversights."
  },
  {
    "name": "Guest House Preta Torami",
    "summary": "Guest House Preta Torami offers affordable accommodation with a homey atmosphere, convenient to the beach and local amenities. Guests praise the friendly owner, bike and surfboard rentals, and well-equipped kitchen, making it a great place to meet fellow travelers."
  },
  {
    "name": "Kujukuri Villa Sotobō",
    "summary": "Kujukuri Villa Sotobō offers hotel rooms and dog-friendly log houses on its grounds. While some guests have praised the beautiful and satisfying dinners, friendly staff, and log house amenities, others have reported issues with cleanliness, slow service, and a lack of explanation regarding dishes."
  },
  {
    "name": "Onjuku Beachside",
    "summary": "Onjuku Beachside offers a good location near the beach, but some guests have reported negative experiences with mosquitos, cockroaches, and filthy bathwater. Paid parking for guests is also a potential concern, despite the friendly owners."
  },
  {
    "name": "Itsukiri",
    "summary": "Itsukiri is a luxurious, dog-friendly glamping hotel blending modern Japanese aesthetics with a relaxing natural setting. Guests rave about the gourmet dining experience featuring local ingredients, the private hot springs, and the exceptional hospitality."
  }
]
```
